<style>.security-grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(280px,.8fr);gap:22px}.security-status{display:flex;align-items:center;gap:16px;padding:18px;border-radius:16px;background:<?= $status['enabled']?'#ecfdf5':'#fff7ed' ?>;border:1px solid <?= $status['enabled']?'#a7f3d0':'#fed7aa' ?>}.security-icon{width:54px;height:54px;border-radius:15px;display:grid;place-items:center;background:#fff;color:<?= $status['enabled']?'#059669':'#d97706' ?>;font-size:1.5rem}.security-form{display:grid;gap:14px}.security-form input{width:100%;padding:12px 13px;border:1px solid var(--line);border-radius:10px;font:inherit}.secret-box{padding:15px;border:1px dashed var(--teal-500);background:#f0fdff;border-radius:12px;word-break:break-all;font-family:monospace;font-size:1rem;letter-spacing:.08em}.security-note{padding:13px 15px;border-radius:12px;background:#eff6ff;color:#1e4f72;font-size:.84rem;line-height:1.55}@media(max-width:850px){.security-grid{grid-template-columns:1fr}}</style></head><body>
